use std::{fs,path::Path,collections::BTreeMap};fn main(){let arg=std::env::args().nth(1).unwrap();let p=Path::new(&arg);let data=fs::read_to_string(p.join("CONTROL.tsv")).unwrap();let prior=fs::read_to_string("research/hec_collision_core_20261116/CERT-CONTROL.tsv").unwrap();let mut groups:BTreeMap<(usize,usize,usize),(usize,usize,usize,usize,usize,usize,usize,usize,usize)>=BTreeMap::new();let(mut total,mut yes,mut support,mut missing,mut partial_rank,mut prefix)=(0,0,0,0,0,0);
for l in data.lines().skip(1){let x:Vec<_>=l.split('\t').collect();let n=|j:usize|x[j].parse::<usize>().unwrap();total+=1;let ok=x[8]=="verified";yes+=usize::from(ok);support+=usize::from(x[8]=="support_exceeds_H");missing+=usize::from(x[8]=="missing_input_row");partial_rank+=usize::from(ok&&n(10)<n(11));assert_eq!(n(26),n(28));assert_eq!(n(26)-n(27),usize::from(ok));let z=groups.entry((n(0),n(6),n(7))).or_insert((0,0,0,0,usize::MAX,0,0,0,0));z.0+=1;z.1+=usize::from(ok);z.2+=usize::from(x[8]=="support_exceeds_H");z.3+=usize::from(x[8]=="missing_input_row");if ok{z.4=z.4.min(n(20));z.5=z.5.max(n(20));}z.6+=n(12);z.7+=n(14);z.8+=usize::from(ok&&n(10)<n(11));
if n(7)==0{let policy=if n(5)==0{2}else{3};let old=prior.lines().skip(1).map(|l|l.split('\t').collect::<Vec<_>>()).find(|v|v[0]==x[0]&&v[1]==x[1]&&v[2]==x[2]&&v[4]==x[4]&&v[5].parse::<usize>().unwrap()==policy).unwrap();for(i,j)in[(7,6),(8,8),(9,9),(10,10),(11,11),(12,14),(13,15),(14,16),(15,17),(16,18),(17,19),(18,20),(19,21),(20,22),(21,23),(22,24),(23,25),(24,26),(25,27),(26,28)]{assert_eq!(old[i],x[j]);}prefix+=1;}}
assert_eq!(total,120);assert_eq!(fs::read(p.join("BASELINE.tsv")).unwrap(),fs::read("research/hec_collision_core_20261116/BASELINE.tsv").unwrap());assert_eq!(fs::read(p.join("INPUTS.txt")).unwrap(),fs::read("research/hec_collision_core_20261116/INPUTS.txt").unwrap());let mut out=String::from("g\tH\tmode\tpolicies\tverified\tsupport_exceeds_H\tmissing_input_row\tverified_prepared_min\tverified_prepared_max\tprep_adds_sum\tanchor_scans_sum\tverified_partial_core_rank\n");for(&(g,h,mode),&(n,v,s,m,lo,hi,pa,sc,pr))in&groups{let low=if v==0{"NA".into()}else{lo.to_string()};let high=if v==0{"NA".into()}else{hi.to_string()};out+=&format!("{g}\t{h}\t{mode}\t{n}\t{v}\t{s}\t{m}\t{low}\t{high}\t{pa}\t{sc}\t{pr}\n");}print!("{out}");fs::write(p.join("SUMMARY.tsv"),out).unwrap();let totals=format!("policies={total}\nverified={yes}\nsupport_exceeds_H={support}\nmissing_input_row={missing}\nother_noncompletion={}\nverified_partial_core_rank={partial_rank}\nprior_prefix_count_vectors_reproduced={prefix}\ncontrol_and_input_bytes_equal=true\n",total-yes-support-missing);print!("{totals}");fs::write(p.join("TOTALS.txt"),totals).unwrap();
let mut svg=String::from("<svg xmlns='http://www.w3.org/2000/svg' width='1100' height='610'><rect width='1100' height='610' fill='white'/><g font-family='Arial' fill='#183846'><text x='35' y='35' font-size='22'>Anchor membership and equation reuse at fixed core sizes</text><text x='35' y='63' font-size='14'>Verified cases out of four per bar; modes3/4pay preparatory descents and reject support larger than H.</text>");for(size,label)in[(0usize,"Half-size core"),(1,"Original-size core")]{for(panel,g)in[2usize,3,4].iter().enumerate(){let hs:Vec<_>=groups.keys().filter(|k|k.0==*g).map(|k|k.1).collect();let h=if size==0{*hs.iter().min().unwrap()}else{*hs.iter().max().unwrap()};let ox=70.+panel as f64*350.;let oy=115.+size as f64*215.;svg+=&format!("<text x='{ox}' y='{oy}' font-size='17'>g{g} / H{h} / {label}</text>");for mode in 0..5{let z=groups.get(&(*g,h,mode)).unwrap();let x=ox+15.+mode as f64*55.;let ht=z.1 as f64*30.;let y=oy+145.-ht;let col=if mode==4{"#b8763e"}else{"#287f82"};svg+=&format!("<rect x='{x}' y='{y}' width='30' height='{ht}' fill='{col}'/><text x='{x}' y='{}' font-size='14'>{}/4</text><text x='{x}' y='{}' font-size='13'>{mode}</text>",y-8.,z.1,oy+166.);}}}
svg+="<text x='35' y='555' font-size='14'>Modes:0prefix;1rotation;2seeded shuffle;3target-support selection;4same support with known equations reused.</text><text x='35' y='585' font-size='13'>hec_anchor_membership_20261116 / exact frozen policy counts; no timing or population estimate.</text></g></svg>";fs::write(p.join("COUNTS.svg"),svg).unwrap();}
